with with_windows as (select *, round(amount / sum(amount) over (partition by merchant), 4) as amount_share, count(amount) over (order by cast(txn_time as bigint) asc range between 604800 preceding and current row) as amount_count_7d from transactions) select case when amount_count_7d >= 13 then 'PREMIUM' else 'STANDARD' end as amount_count_7d_tier, sort_array(collect_set(merchant)) as merchant_list, sum(case when merchant = 'Amazon' then amount_share else 0 end) as amazon_amount_share from with_windows group by case when amount_count_7d >= 13 then 'PREMIUM' else 'STANDARD' end order by amount_count_7d_tier desc nulls first;
